<?php require 'config/config.php'; layout_header('Home');
$products = db()->query("SELECT p.*, u.username AS farmer_name FROM products p JOIN users u ON u.id=p.farmer_id WHERE p.stock_quantity>0 ORDER BY p.id DESC LIMIT 8")->fetchAll();
$markets = db()->query("SELECT m.*,COUNT(mp.product_id) product_count FROM markets m LEFT JOIN market_products mp ON mp.market_id=m.id GROUP BY m.id ORDER BY m.id DESC LIMIT 6")->fetchAll();
$shops = db()->query("SELECT s.*,COUNT(DISTINCT spp.product_id) product_count,MIN(spp.price) low_price FROM shops s LEFT JOIN shop_product_prices spp ON spp.shop_id=s.id GROUP BY s.id ORDER BY s.id LIMIT 6")->fetchAll();
?>
