<div class="d-flex justify-content-between align-items-center mb-3"><h2 class="section-title">Shops & lower listed prices</h2><button class="btn btn-sm btn-success" onclick="findHomeNearMe()">📍 Near me</button></div><div class="row g-3 mb-5" id="homeShops"><?php foreach($shops as $s): ?><div class="col-md-6 col-lg-4 home-shop" data-lat="<?=$s['latitude']?>" data-lng="<?=$s['longitude']?>"><div class="card p-3 h-100"><span class="badge bg-success-subtle text-success mb-2"><?=e(ucwords(str_replace('_',' ',$s['shop_type'])))?></span><h5><?=e($s['shop_name'])?></h5><p class="small mb-1">📍 <?=e($s['area'])?></p><strong class="text-success">From <?=money((float)$s['low_price'])?></strong><small class="text-muted d-block mt-1">Lowest listed demo price; confirm at shop.</small><a href="markets.php" class="btn btn-outline-success mt-3">View shop & map</a></div></div><?php endforeach; ?></div>
<div class="d-flex justify-content-between align-items-center mb-3"><h2 class="section-title">Fresh this week</h2><a href="products.php">View all</a></div><div class="row g-4"><?php foreach($products as $p): ?><div class="col-md-6 col-lg-3"><div class="card h-100 product-card"><div class="product-img"><img src="<?=e(product_image($p['name'],$p['category'],$p['image_url'] ?? ''))?>" alt="<?=e($p['name'])?>" loading="lazy" onerror="this.onerror=null;this.src='assets/img-placeholder.svg';"></div><div class="card-body"><small class="text-muted"><?=e($p['category'])?></small><h5><?=e($p['name'])?></h5><p class="small text-muted mb-2">by <?=e($p['farmer_name'])?></p><strong class="price"><?=money((float)$p['price'])?></strong> / <?=e($p['unit'])?><a class="btn btn-outline-success w-100 mt-3" href="product.php?id=<?=$p['id']?>">View</a></div></div></div><?php endforeach; ?></div>
<script>function hh(a,b,c,d){const R=6371,r=x=>x*Math.PI/180,x=r(c-a),y=r(d-b),h=Math.sin(x/2)**2+Math.cos(r(a))*Math.cos(r(c))*Math.sin(y/2)**2;return 2*R*Math.asin(Math.sqrt(h));}function findHomeNearMe(){if(!navigator.geolocation){alert('Location not supported.');return;}navigator.geolocation.getCurrentPosition(p=>{[...document.querySelectorAll('.home-shop')].sort((x,y)=>hh(p.coords.latitude,p.coords.longitude,+x.dataset.lat,+x.dataset.lng)-hh(p.coords.latitude,p.coords.longitude,+y.dataset.lat,+y.dataset.lng)).forEach(x=>document.getElementById('homeShops').appendChild(x));alert('Nearby shops sorted from nearest to farthest.');},()=>alert('Please allow location access.'));}</script>
